const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(now.getDate() - 1);

const fmt = (d) => {
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const yyyy = d.getFullYear();
  return `${mm}/${dd}/${yyyy}`;
};

const isoDate = yesterday.toISOString().split('T')[0];

return [{
  json: {
    startDate: fmt(yesterday),
    endDate: fmt(yesterday),
    isoDate: isoDate
  }
}];

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

const future = new Date();
future.setDate(yesterday.getDate() + 30);

const pad = n => String(n).padStart(2, '0');
const fmt = d => `${pad(d.getMonth()+1)}/${pad(d.getDate())}/${d.getFullYear()}`;

return [{ json: {
  startDate: fmt(yesterday),
  endDate: fmt(future)
}}];

const raw = $input.all()[0].json.data;
