const raw = $input.first().json.data;
const parsed = JSON.parse(raw);
const total = parsed.message.totalResults;
const pages = Math.ceil(total / 200);

const result = [];
for (let i = 1; i <= pages; i++) {
  result.push({ json: { page: i } });
}
return result;

