const raw = JSON.parse($input.first().json.data);
const message = raw.message;
const results = [];

for (const [campaignKey, campaignData] of Object.entries(message)) {
  const campaignId = campaignData.id;
  const campaignName = campaignKey;

  for (const [key, value] of Object.entries(campaignData)) {
    if (key === 'id') continue;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(key)) continue;

    results.push({
      json: {
        campaign_id: campaignId,
        campaign_name: campaignName,
        billing_date: key,
        projected_count: parseInt(value.count) || 0,
        projected_revenue: parseFloat(value.revenue.replace(/[$,]/g, '')) || 0,
        ingested_at: new Date().toISOString()
      }
    });
  }
}

return results;
